func (q *Queries) ListUnblockedAgentTasks(ctx context.Context, userID string) ([]AgentTask, error) {
	rows, err := q.db.QueryContext(ctx, listUnblockedAgentTasks, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AgentTask{}
	for rows.Next() {
		var i AgentTask
		if err := rows.Scan(
			&i.ID,
			&i.ParentID,
			&i.RootID,
			&i.TaskType,
			&i.Title,
			&i.Description,
			&i.Status,
			&i.Priority,
			&i.Required,
			&i.RetryCount,
			&i.MaxRetries,
			&i.ReviewPolicy,
			&i.SessionID,
			&i.Context,
			&i.ReviewRequest,
			&i.NotifyAt,
			&i.SchedulerJobID,
			&i.SchedulerRunID,
			&i.AssigneeAgentID,
			&i.CreatedByAgentID,
			&i.UserID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

